      paragraphs: [
        `CAPÍTULO 41`,
        `Desejo ansioso do real profeta de ver o tabernáculo do Senhor, quando andava ausente por causa da perseguição ou de Saul, ou de Absalão.`,
        `1. Instrução aos filhos de Coré.`,
        `2. Assim como o servo suspira pelas fontes das águas: assim a minha alma suspira por ti, ó Deus.`,
        `3. A minha alma está ardendo de sede pelo Deus forte e vivo: quando virei e aparecerei diante da face de Deus.`,
        `4. As minhas lágrimas foram o meu pão de dia e de noite: enquanto se me diz cada dia: Onde está o teu Deus?`,
        `5. Eu me lembrei destas coisas, e derramei a minha alma dentro de mim: porque eu passarei ao lugar do tabernáculo admirável, até à casa de Deus: com voz de regozijo, e louvor: som festivo de quem se banqueteia.`,
        `6. Por que estás triste, alma minha? e por que me conturbas? Espera em Deus, porque eu ainda tenho de o louvar: salvação do meu rosto, e Deus meu.`,
        `7. Dentro de mim mesmo está conturbada a minha alma: pelo que me lembrarei de ti na terra de Jordão, e de Hermon desde o monte pequeno.`,
        `8. Um abismo chama outro abismo, à voz das tuas cataratas. Todas as tuas coisas altas, e as tuas ondas sobre mim passaram.`,
        `9. No dia enviou o Senhor a sua misericórdia e de noite o seu cântico. Dentro de mim orarei ao Deus de minha vida`,
        `10. dizendo a Deus: Tu és meu amparador. Por que te esqueceste de mim? e por que ando triste enquanto me aflige o inimigo?`,
        `11. Ao tempo que os meus ossos se quebram, me improperam os meus inimigos que me perseguem: dizendo-me todos os dias: Onde está o teu Deus?`,
        `12. Por que estás tu triste, alma minha? e por que me conturbas? Espera em Deus, porque ainda tenho de o louvar: salvação do meu rosto, e Deus meu.`,
      ],
