      paragraphs: [
        `CAPÍTULO 150`,
        `Salmo gratulatório. Que se há de louvar o Senhor, porque só ele é digno de que se louve de todas as maneiras.`,
        `1. Aleluia. Louvai ao Senhor no seu santuário: louvai-o no firmamento da sua virtude.`,
        `2. Louvai-o nas virtudes dele: louvai-o segundo a multidão da sua grandeza.`,
        `3. Louvai-o ao som da trombeta: louvai-o com saltério e cítara.`,
        `4. Louvai-o com adufe e flauta: louvai-o com cordas, e órgão.`,
        `5. Louvai-o com címbalos sonoros: louvai-o com címbalos de júbilo:`,
        `6. Todo o espírito louve o Senhor. Aleluia.`,
      ],
